function validate([edges, queries]) {
  if (!Array.isArray(edges)) return 'edges must be a list of [u, v, w] edges.';
  const n = edges.length + 1;
  if (n < 3 || n > 100000) return 'The tree has 3 to 10^5 nodes, so edges has 2 to 10^5 - 1 entries.';
  const parent = Array.from({ length: n }, (_, i) => i);
  const find = (x) => { while (parent[x] !== x) { parent[x] = parent[parent[x]]; x = parent[x]; } return x; };
  for (const edge of edges) {
    if (!Array.isArray(edge) || edge.length !== 3 || !edge.every(Number.isInteger)) return 'Each edge is [u, v, w] with integers.';
    const [u, v, w] = edge;
    if (u < 0 || v < 0 || u >= n || v >= n) return 'Edge endpoints are between 0 and n - 1, where n = edges.length + 1.';
    if (w < 1 || w > 10000) return 'Edge weights are between 1 and 10^4.';
    const ru = find(u), rv = find(v);
    if (ru === rv) return 'edges must form a tree (no cycles or repeated edges).';
    parent[ru] = rv;
  }
  if (!Array.isArray(queries) || queries.length < 1 || queries.length > 100000) return 'queries has 1 to 10^5 entries.';
  for (const query of queries) {
    if (!Array.isArray(query) || query.length !== 3 || !query.every(x => Number.isInteger(x) && x >= 0 && x < n)) return 'Each query is [src1, src2, dest] with nodes between 0 and n - 1.';
    const [src1, src2, dest] = query;
    if (src1 === src2 || src2 === dest || dest === src1) return 'The three nodes of a query must be different.';
  }
  return null;
}

