function minimumWeight(edges, queries) {
  const n = edges.length + 1;
  const graph = Array.from({ length: n }, () => []);
  for (const [u, v, w] of edges) {
    graph[u].push([v, w]);
    graph[v].push([u, w]);
  }

  const LOG = Math.max(1, Math.ceil(Math.log2(n)));
  const up = Array.from({ length: LOG }, () => new Array(n).fill(0));
  const depth = new Array(n).fill(0);
  const dist = new Array(n).fill(0);
  const visited = new Array(n).fill(false);
  const queue = [0];
  visited[0] = true;

  for (let head = 0; head < queue.length; head++) {
    const node = queue[head];
    for (const [next, w] of graph[node]) {
      if (visited[next]) continue;
      visited[next] = true;
      up[0][next] = node;
      depth[next] = depth[node] + 1;
      dist[next] = dist[node] + w;
      queue.push(next);
    }
  }

  for (let j = 1; j < LOG; j++) {
    for (let v = 0; v < n; v++) {
      up[j][v] = up[j - 1][up[j - 1][v]];
    }
  }

  const lca = (a, b) => {
    if (depth[a] < depth[b]) [a, b] = [b, a];
    for (let j = LOG - 1; j >= 0; j--) {
      if (depth[a] - (1 << j) >= depth[b]) a = up[j][a];
    }
    if (a === b) return a;
    for (let j = LOG - 1; j >= 0; j--) {
      if (up[j][a] !== up[j][b]) {
        a = up[j][a];
        b = up[j][b];
      }
    }
    return up[0][a];
  };

  const distance = (a, b) => dist[a] + dist[b] - 2 * dist[lca(a, b)];

  return queries.map(([src1, src2, dest]) => {
    const total = distance(src1, src2) + distance(src2, dest) + distance(dest, src1);
    return total / 2;
  });
}

