function minimumWeight(edges, queries) {
  // For each query, walk the two tree paths into dest and add every edge they use exactly once.
  const n = edges.length + 1;
  const neighbours = Array.from({ length: n }, () => []);
  edges.forEach(([u, v], id) => { neighbours[u].push([v, id]); neighbours[v].push([u, id]); });
  return queries.map(([src1, src2, dest]) => {
    const parent = new Array(n).fill(-1);
    const parentEdge = new Array(n).fill(-1);
    const seen = new Array(n).fill(false);
    seen[dest] = true;
    const stack = [dest];
    while (stack.length) {
      const x = stack.pop();
      for (const [y, id] of neighbours[x]) if (!seen[y]) { seen[y] = true; parent[y] = x; parentEdge[y] = id; stack.push(y); }
    }
    const used = new Set();
    for (const start of [src1, src2]) for (let x = start; x !== dest; x = parent[x]) used.add(parentEdge[x]);
    let total = 0;
    for (const id of used) total += edges[id][2];
    return total;
  });
}

