function generate(rand, size) {
  const pick = (k) => Math.floor(rand() * k);
  const n = size === 'large' ? 2000 : 3 + pick(8);
  const shape = rand();
  const maxWeight = size === 'large' || rand() < 0.5 ? 10000 : 1 + pick(4);
  // Build a tree on positions 0..n-1 (each joins an earlier one), then relabel the nodes at random.
  const label = Array.from({ length: n }, (_, i) => i);
  for (let i = n - 1; i > 0; i--) { const j = pick(i + 1); [label[i], label[j]] = [label[j], label[i]]; }
  const edges = [];
  for (let i = 1; i < n; i++) {
    // Paths make deep trees, stars shallow ones, and a recent parent gives long branches.
    const parent = shape < 0.25 ? i - 1 : shape < 0.4 ? 0 : shape < 0.7 ? Math.max(0, i - 1 - pick(3)) : pick(i);
    const edge = [label[parent], label[i], 1 + pick(maxWeight)];
    if (rand() < 0.5) [edge[0], edge[1]] = [edge[1], edge[0]];
    edges.push(edge);
  }
  for (let i = edges.length - 1; i > 0; i--) { const j = pick(i + 1); [edges[i], edges[j]] = [edges[j], edges[i]]; }
  const m = size === 'large' ? 2000 : 1 + pick(6);
  // Each query takes three different nodes.
  const queries = Array.from({ length: m }, () => {
    const a = pick(n);
    let b = pick(n - 1);
    if (b >= a) b++;
    let c = pick(n);
    while (c === a || c === b) c = pick(n);
    return [a, b, c];
  });
  return [edges, queries];
}
